 const resolved=await (dependencies.resolveAddresses??resolveAddresses)(origins(prepared.ready.plan.value)),networkUnsigned={version:1 as const,origins:origins(prepared.ready.plan.value),path_prefixes:prepared.ready.network.value.profile.path_prefixes,resolved_addresses:resolved,deny_private_addresses:true as const,max_response_bytes:prepared.ready.network.value.profile.max_response_bytes},networkProfile={...networkUnsigned,profile_hash:hash(networkUnsigned)},task={version:1 as const,plan:prepared.ready.plan.value,approval:prepared.approval.value,grant:prepared.grant.value,observation_profile:prepared.ready.observation.value.profile as FaultlineObservationProfile,network_profile:networkProfile,deployments:prepared.deployments,value_refs:prepared.values,task:{job_id:job.id,lease_id:job.fence,nonce,expires_at:prepared.expiresAt,plan_hash:prepared.ready.plan.plan_hash,approval_hash:prepared.approval.approval_hash,grant_hash:prepared.grant.grant_hash,observation_profile_hash:prepared.ready.plan.value.observation_profile_hash,network_profile_hash:networkProfile.profile_hash,runner_id:prepared.ready.plan.value.runner_id}},requestHash=hash(task);
