 demand(run&&receipt&&candidate&&run.receipt_hash===hash(receipt)&&receipt.status==='completed'&&receipt.task_sha256===run.request_hash&&receipt.result_sha256===hash(candidate)&&candidate.job_id===run.job_id&&candidate.lease_id===run.fence&&candidate.nonce===run.nonce&&candidate.plan_hash===plan.plan_hash,'RUNNER_RESULT_BINDING_MISMATCH','Stored external evidence does not bind its published run.',503);const result=candidate as ExternalTaskResult;
